important;background:#fff}.rb-category-slider{position:relative;padding:0 58px}.rb-category-viewport{overflow:hidden}.rb-category-slider .rb-category-row{display:flex!important;gap:28px!important;will-change:transform;transition:transform .55s cubic-bezier(.22,.61,.36,1)}.rb-category-slider .rb-category-card{flex:0 0 calc((100% - 112px)/5);min-width:0;text-align:center}.rb-category-slider .rb-category-card span{width:100%;aspect-ratio:1.45/1;display:flex;align-items:flex-end;justify-content:center;border:0!important;border-radius:0 0 50% 50%!important;background:linear-gradient(180deg,#fff 0 28%,#f3d9a7 28% 100%)!important;box-shadow:none!important;overflow:hidden}.rb-category-slider .rb-category-card img{width:88%!important;height:88%!important;object-fit:contain!important;object-position:center bottom!important}.rb-category-slider .rb-category-card b{margin-top:11px;font-size:15px;font-weight:500;color:#282222}.rb-category-slider .rb-category-card:hover span{transform:none!important;box-shadow:none!important}.rb-category-arrow{position:absolute;top:43%;z-index:3;width:48px;height:48px;display:grid;place-items:center;border:1px solid #e8e1dd;border-radius:50%;background:#fff;color:#5b5552;font-size:32px;line-height:1;box-shadow:0 7px 22px rgba(0,0,0,.10);cursor:pointer;transform:translateY(-50%);transition:.2s}.rb-category-arrow:hover{background:#5b1624;color:#fff;border-color:#5b1624}.rb-category-arrow--prev{left:0}.rb-category-arrow--next{right:0}@media(max-width:980px){.rb-category-slider{padding:0 52px}.rb-category-slider .rb-category-row{gap:22px!important}.rb-category-slider .rb-category-card{flex-basis:calc((100% - 44px)/3)}}@media(max-width:560px){.rb-category-slider-section{padding:36px 0 44px!important}.rb-category-slider{padding:0 38px}.rb-category-slider .rb-category-row{gap:14px!important}.rb-category-slider .rb-category-card{flex-basis:calc((100% - 14px)/2)}.rb-category-slider .rb-category-card b{font-size:12px}.rb-category-arrow{width:34px;height:34px;font-size:24px}.rb-category-arrow--prev{left:-2px}.rb-category-arrow--next{right:-2px}}</style><script id="ruwah-category-loop-script">document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('[data-category-slider]').forEach(function(slider){var viewport=slider.querySelector('.rb-category-viewport'),track=slider.querySelector('[data-category-track]'),prev=slider.querySelector('[data-category-prev]'),next=slider.querySelector('[data-category-next]');if(!viewport||!track)return;var originals=Array.from(track.children),index=0,visible=5,timer=null,busy=false;function count(){return window.innerWidth<=560?2:(window.innerWidth<=980?3:5)}function gap(){var value=parseFloat(getComputedStyle(track).columnGap||getComputedStyle(track).gap);return isNaN(value)?0:value}function step(){var card=track.querySelector('.rb-category-card');return card?card.getBoundingClientRect().width+gap():0}function paint(animate){track.style.transition=animate?'transform .55s cubic-bezier(.22,.61,.36,1)':'none';track.style.transform='translate3d('+(-index*step())+'px,0,0)'}function build(){visible=count();index=0;track.style.transition='none';track.innerHTML='';originals.forEach(function(card){track.appendChild(card)});originals.slice(0,visible).forEach(function(card){track.appendChild(card.cloneNode(true))});paint(false)}function go(direction){if(busy||originals.length<=visible)return;busy=true;if(direction>0){index++;paint(true);if(index===originals.length){setTimeout(function(){index=0;paint(false);busy=false},570)}else{setTimeout(function(){busy=false},570)}}else{if(index===0){index=originals.length;paint(false);requestAnimationFrame(function(){requestAnimationFrame(function(){index--;paint(true);setTimeout(function(){busy=false},570)})})}else{index--;paint(true);setTimeout(function(){busy=false},570)}}}function stop(){if(timer){clearInterval(timer);timer=null}}function start(){stop();if(originals.length>visible)timer=setInterval(function(){go(1)},2800)}build();start();next&&next.addEventListener('click',function(){go(1);start()});prev&&prev.addEventListener('click',function(){go(-1);start()});slider.addEventListener('mouseenter',stop);slider.addEventListener('mouseleave',start);slider.addEventListener('focusin',stop);slider.addEventListener('focusout',start);var resizeTimer;window.addEventListener('resize',function(){clearTimeout(resizeTimer);resizeTimer=setTimeout(function(){build();start()},180)});});});</script><section class="rb-section rb-section--blush"><div class="rb-shell"><header class="rb-section-head rb-section-head--split"><div><span class="rb-kicker">FRESHLY ADDED</span><h2>New arrivals</h2></div><a class="rb-text-link" href="<?php echo esc_url(add_query_arg('orderby','date',ruwah_shop_url())); ?>">View all products</a></header><div class="rb-product-grid"><?php foreach(array_slice($products,0,8) as $p)ruwah_product_card($p,'New'); ?></div></div></section><section class="rb-section"><div class="rb-shell rb-promo-grid"><article class="rb-promo"><span class="rb-kicker" style="color:#fff">PERSONALISED CARE</span><h3>Build your glow routine.</h3><p>Choose a simple routine around your skin type and concern.</p><a class="rb-button rb-button--light" href="<?php echo esc_url(ruwah_page_url('routine-builder')); ?>">Start routine finder</a></article><article class="rb-promo"><span class="rb-kicker">BETTER TOGETHER</span><h3>Save more with bundles.</h3><p>Complete routines with products designed to work together.</p><a class="rb-button" href="<?php echo esc_url(ruwah_page_url('bundles')); ?>">Shop bundles</a></article></div></section><section class="rb-section rb-section--blush"><div class="rb-shell"><header class="rb-section-head"><span class="rb-kicker">SHOP BY CONCERN</span><h2>Care focused on what matters to you.</h2></header><div class="rb-concern-grid"><?php foreach(['Acne & Breakouts','Pigmentation','Dryness','Dullness','Sun Damage','Texture & Pores','Fine Lines','Sensitive Skin'] as $concern)echo '<a class="rb-conc